content.value:
:root {
  --ink: #17201d;
  --muted: #5b6964;
  --line: #d7ded9;
  --paper: #f7f8f5;
  --panel: #ffffff;
  --red: #b51d1a;
  --green: #2f6f5e;
  --blue: #2b5b7e;
  --gold: #9b6b2f;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "Segoe UI", "Microsoft YaHei", Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.65;
}
a { color: inherit; }
.hero {
  min-height: 78vh;
  display: grid;
  align-items: end;
  background-image: linear-gradient(90deg, rgba(12,18,16,.88), rgba(12,18,16,.58) 44%, rgba(12,18,16,.16)), url("showcase_assets/showcase-recognition.jpg");
  background-size: cover;
  background-position: center;
  color: #fff;
  padding: 48px 6vw 56px;
}
.hero-inner { max-width: 980px; }
.eyebrow {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  font-size: 13px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #dbe8e2;
  margin-bottom: 18px;
}
.eyebrow::before { content: ""; width: 38px; height: 2px; background: #e1473e; display: inline-block; }
h1 { margin: 0; max-width: 980px; font-size: clamp(38px, 6vw, 78px); line-height: 1.04; letter-spacing: 0; font-weight: 760; }
.lead { max-width: 820px; margin: 22px 0 0; color: #edf3ef; font-size: clamp(17px, 2.1vw, 22px); }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.button {
  border: 1px solid rgba(255,255,255,.54);
  color: #fff;
  text-decoration: none;
  padding: 10px 16px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 650;
  background: rgba(255,255,255,.08);
}
.button.primary { background: #c52b24; border-color: #c52b24; }
.button.dark { color: var(--ink); border-color: var(--line); background: #fff; }
main { overflow: hidden; }
section { padding: 72px 6vw; }
.section-inner { max-width: 1180px; margin: 0 auto; }
.section-kicker { color: var(--red); font-weight: 750; margin: 0 0 8px; }
h2 { font-size: clamp(28px, 3.5vw, 46px); line-height: 1.14; margin: 0 0 18px; letter-spacing: 0; }
h3 { letter-spacing: 0; }
.intro-grid, .split { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(300px, .95fr); gap: 42px; align-items: start; }
.stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.stat { border: 1px solid var(--line); background: var(--panel); padding: 18px; min-height: 112px; }
.stat strong { display: block; font-size: 28px; line-height: 1.1; color: var(--green); }
.stat span { color: var(--muted); font-size: 14px; }
.reason-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; margin: 30px 0 34px; }
.reason { background: #fff; border: 1px solid var(--line); border-left: 4px solid var(--green); padding: 20px 22px; }
.reason:nth-child(2) { border-left-color: var(--blue); }
.reason:nth-child(3) { border-left-color: var(--gold); }
.reason h3 { margin: 0 0 8px; font-size: 21px; }
.reason p { margin: 0; color: var(--muted); }
.workflow { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; background: transparent; border: 0; }
.step { background: #fff; border: 1px solid var(--line); min-height: 100%; overflow: hidden; }
.step img { width: 100%; display: block; aspect-ratio: 4 / 3; object-fit: contain; background: #fff; border-bottom: 1px solid var(--line); }
.step-body { padding: 18px 20px 20px; }
.step b { display: block; color: var(--red); font-size: 14px; margin-bottom: 8px; }
.step h3 { margin: 0 0 10px; font-size: 20px; line-height: 1.25; }
.step p { margin: 0; color: var(--muted); font-size: 15px; }
.gallery { display: grid; grid-template-columns: repeat(12, 1fr); gap: 18px; }
.figure { background: #fff; border: 1px solid var(--line); overflow: hidden; margin: 0; }
.figure.wide { grid-column: span 12; }
.figure.half { grid-column: span 6; }
.figure.third { grid-column: span 4; }
.figure img { width: 100%; display: block; aspect-ratio: 16 / 9; object-fit: contain; background: #fff; }
.figure.wide img { aspect-ratio: 21 / 9; }
.figure.tall img { aspect-ratio: 4 / 3; }
figcaption { padding: 14px 16px 16px; border-top: 1px solid var(--line); }
figcaption strong { display: block; margin-bottom: 4px; }
figcaption span { color: var(--muted); font-size: 14px; }
.dark-band { background: #17201d; color: #f5f7f3; }
.dark-band .section-kicker { color: #f28b83; }
.dark-band p { color: #d7e0da; }
.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.card { border: 1px solid rgba(255,255,255,.18); padding: 20px 22px; background: rgba(255,255,255,.04); min-height: 210px; }
.card.light { border: 1px solid var(--line); background: #fff; }
.card .tag { display: inline-block; color: #f9d9d6; font-size: 13px; font-weight: 750; margin-bottom: 6px; }
.card.light .tag { color: var(--red); }
.card h3 { margin: 0 0 10px; font-size: 22px; line-height: 1.25; }
.card p { margin: 0; color: inherit; }
.card.light p { color: var(--muted); }
.language-page { min-height: 100vh; display: grid; place-items: center; padding: 40px 6vw; background: linear-gradient(120deg, #17201d, #27483f); color: #fff; }
.language-box { max-width: 900px; width: 100%; }
.language-box h1 { font-size: clamp(36px, 6vw, 72px); }
.language-options { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 28px; }
.footer { padding: 32px 6vw 44px; border-top: 1px solid var(--line); color: var(--muted); font-size: 14px; }
@media (max-width: 1040px) { .workflow, .reason-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } .cards { grid-template-columns: 1fr; } }
@media (max-width: 900px) {
  .hero { min-height: 72vh; padding-top: 38px; }
  .intro-grid, .split { grid-template-columns: 1fr; }
  .figure.half, .figure.third { grid-column: span 12; }
}
@media (max-width: 560px) {
  section { padding: 52px 20px; }
  .hero { padding: 36px 20px 44px; }
  .workflow, .stats, .reason-grid { grid-template-columns: 1fr; }
  .button { width: 100%; justify-content: center; }
}
